import{_ as a,c as e,o as r,af as t}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"卦用第九","description":"杭氏易學 - 卦用第九","frontmatter":{"title":"卦用第九","description":"杭氏易學 - 卦用第九"},"headers":[],"relativePath":"classics/hangshi/010.md","filePath":"classics/hangshi/010.md"}'),i={name:"classics/hangshi/010.md"};function s(n,p,h,l,c,o){return r(),e("div",null,[...p[0]||(p[0]=[t('<h1 id="卦用第九" tabindex="-1">卦用第九 <a class="header-anchor" href="#卦用第九" aria-label="Permalink to “卦用第九”">​</a></h1><p>八卦名位象數氣候既明，而用可得言矣。大用大效，小用小效，大小雖殊，其理則一。《彖》、《象》十翼，皆以明用。而無一辭一字，不根於象數。自象數失傳，專尚夫辭。乃望文生義，以今概古，論愛惡不出六爻之外，言變化限於兩象之中。而《彖》、《象》十翼之大義，不明於世也久矣。朱子《本義》，遂以《易》為聖人教人卜筮之書，以占卜為《大易》之本義。後之學者，既宗程朱，又蔑視數學小道而不屑言，是欲渡而去其楫，卒致占卜之用亦無可徵驗，反不若壬、遁、火珠之術為足憑。《易》道之大，乃盡失其用。舉世徒震其名，視為神秘杳渺而莫敢問津。嗚呼！是誰之過哉！</p><p>行遠自邇，登高自卑，乾簡坤易，古聖已詔我矣。近取諸身，簡之至也。遠取諸物，易之至也。故又曰：《易》簡而天下之理得矣。天下之理得，而用無不彰。其為用焉，孰大於是？京氏八宮世應飛伏之說，經學家素鄙為術數，而不入於經傳。而其為用簡易，深合於乾坤之變化。朱子知其用，以囿於世故，不敢昌言，僅取八宮世應歌訣，列《本義》之前，亦與隱名注《參同契》。同一苦心也。程子《易傳》，雖自稱尚辭，亦不能廢陰陽世應之例。術家專取八宮身世遊歸飛伏之用，而又不明乾坤簡易之理，逐末忘本，與經生之有體無用，同一蔽也。</p><p>頻年講習，博考周諮，始知三《易》之卦爻象數，同源共貫。京氏之學，實遠符《連山》之歷數，近合《周易》之變通。稽諸經傳，證例正多，爰取為立用之準。有精於術數者，更深求之。以推衍《彖》、《象》十翼之辭，其相得有合者，必不止如吾之所知。知無盡而無窮，占卜云乎哉！</p><p>乾伸二用</p><p>《易》之大用，孔子《系傳》，言之詳矣。特後儒類以文字釋之，致孔子之徵言精義，皆忽略讀過，而莫名其蘊蓄宏深之妙。果能以孔子之言，一一以八卦之象數證之，則一字一義，無不各有體用之所在，亦無不各與象數相發明，而“為用不窮”一語決非以空言了之者也。八卦之用，皆本於乾坤，後天坎離代乾坤之用，而六十四卦之用，莫不由乾坤而生。孔子曰：“剛柔相摩，八卦相蕩。鼓之以雷霆，潤之以風雨。日月運行，一寒一暑。乾道成男，坤道成女。”天地萬物之用，備於是矣 【雷霆震與艮風雨巽與兌皆相反之卦也，日月坎離與乾坤皆相對之卦也。詳玩其象，八卦之用可悟矣。】 。而又承之以“乾知大始，坤作成物”。《易》之大用，孰逾於是？故乾用九，坤用六。六十四卦，皆乾坤之用，皆九六之用。乾無方體用不可見，故乾九之用，用於坤六。《傳》曰：“顯諸仁，藏諸用。”乾顯而坤藏，惟藏而用乃顯焉。乾坤象也，九六數也。象數不明，用何由顯？為圖如左，餘卦類推。</p><p>端木鶴田曰：“乾坤天地一二，始子復一，醜臨二。而臨二坎爻，其初復一震爻。天地一二子醜數造始 【坎震屯】 ，一主日，二主月。子復一交午七數，為復‘七日吉’。醜臨二交未八數，為臨‘八月兇’。故七八正當子醜一二正位。《易》，七八數之正也，九六數之變也。七吉以七而九進為用，午進而七數之正。進而用九數之變，乾用九是也。八兇以八而六退為用，未退而八數之正，退而用六數之變，坤用六是也。六坎數，九震數，皆天地一二造始數。乾坤卦用七八正爻用九六變，此其數是也。”</p><p>晁氏公武曰：“餘有志學《易》，本好王氏，妄謂弼之外，自有名象者。果得京氏傳，而文字顛倒舛訛，不可訓知。迨其服習甚久，漸有所窺，今二十有四年矣。乃能以其象數辨正文字，而私識之曰：是書兆乾坤之二象以成八卦，凡八變而六十有四，於其往來升降之際，以觀消息盈虛於天地之元，而酬酢乎萬物之來者，炳然在日也。大抵辨三《易》，運五行，正四時，謹二十四氣，志七十二候，而位五星，降二十八宿，其進退以幾，為一卦之主者謂之世。奇耦相與，據一以起二而為主之相者謂之應。世之所位而陰陽之肆者，謂之飛。陰陽肇乎所配，而終不脫乎本，以應顯佐神明者謂之伏。起乎世而周乎內外，參乎本數以紀月者謂之建。終之始之，極乎數而不可窮以紀日者，謂之積。會於中而以四為用，一卦備四卦者，謂之互。乾建於甲子於下，坤建於甲午於上。八卦之上，乃生一世之初，分五世之位。其五世之上，乃為遊魂之世。五世之初，乃為歸魂之世。而歸魂之初，乃生後卦之初。其建剛日剛節氣，柔日則中氣，其數虛則二十有八，盈則三十有六。其可言者如此。”晁氏之說，可謂挈《京易》之綱領矣。茲分列八宮暨飛伏諸例如下，若應與配位五行六神諸說，詳下《爻位》、《爻數》各章。</p><p>八純卦各以五行所屬為主，乾金坎水艮土震木巽木離火坤土兌金，所謂進退以幾而為一卦之主者謂之世也。本宮不變，初爻變為一世，至五爻變為五世，上爻六世，即本宮，謂之宗廟不變。初至七世仍以三爻變為遊魂，八世下三爻，全複本宮，為歸魂。故二世為地《易》，三四世為人《易》，五六世為天《易》，遊魂歸魂為鬼《易》。</p><p>乾坎艮震巽離坤兌之序，決非京氏所創。《系傳》曰：“乾知大始，坤作成物。”雖乾坤對舉，而詳玩後天八卦方位，及六十四卦之次序，所謂“仰以觀於天文，俯以察於地理。天道下濟，地道上行”者，皆足以見八宮之用，即分陰分陽之大義也。八卦東震西兌，東西平衡，若地平線。故巽離坤三陰卦，實處於地之上，所謂地道卑而上行也。而乾坎艮三陽卦，皆處於地之下，所謂天道下濟也。上下以震兌為始終，故雷澤歸妹曰“天地大義人終始”者此也。震之始，始於乾，“乾知大始”也。兌之終，終於坤，坤“代終”也。三《易》之卦，爻象皆同，不同者其序耳。八宮之序，或謂出於《連山》，非無所見也。</p><p>世卦月卦</p><h3 id="世應" tabindex="-1">世應 <a class="header-anchor" href="#世應" aria-label="Permalink to “世應”">​</a></h3><p>《周易》雖無八宮之別，而世應仍所不廢。惟《周易》之世應，但以爻論，而京《易》則特重在卦。京氏曰“卦有八世爻分六位，配乎人事，以定吉凶”者，固不僅為占筮言也。《易乾鑿度》曰：“三畫以下為地，四畫以上為天。易氣從下生，動於地之下，則應於天之上。動於地之中，則應於天之中。動於地之上，則應於天之上 【此以上下二象分天地，故不曾人。人秉天地之氣以生，一身之陰陽之氣亦有感必應。言其精則水火升降，言其粗則脈絡之交布，穴氣之分行。與夫一身外相所表見者，無不各按其位，而上下相應。如人身上部口面耳目間有痣者，下部相應之位亦必有之，毫釐不爽。此上下相應之最顯而易見者也。一卦六爻亦如一身上下相通，如有否隔，即為疵病。天地人物，因無二理也。】 。”</p><p>初與四，二與五，三與上，陰應陽，陽應陰，二氣感應以相與，此其正也。蓋天地之氣有終始，六世之位有上下，故《易》始於一 【《易》本無體，氣變而為一，故氣從下生也。】 ，分於二 【清濁分於二儀。公武曰：奇偶相與，據一以起二，而為主之相者，謂之應是也。】 ，通於三 【陰陽氣交，人生於中。天地氣通，故三陽成泰，而泰為通。】 ，交於四，盛於五 【二壯於地，五壯於天，故如盛也】 ，終於上 【上則數極，極則反也】 。故六爻皆有應，而世取其一。與世對者，則為應也。</p><p>水火既濟 ䷾，初陽而四陰，二陰而五陽，三陽而上陰，所謂六爻當位、上下皆相應者者也。既濟屬坎宮三世卦，三之應在上。</p><p>火水未濟 ䷿，既濟之反也。六爻皆不當位，而上下剛柔相應，屬離宮三世卦應亦在上。</p><p>月卦非月建，由世卦生，亦由十二月闢卦生者也。世分陰陽，陽世起子月，陰世起午月，以數不以氣。雖以闢卦為綱，而不去坎離震兌，仍以六十四卦配八宮之屬也。</p><p>乾 ䷀ 為本宮，上爻六世，陽爻陽世，從初爻子月起數至上爻為巳，故乾為四月卦。</p><p>豐 ䷶ 為坎宮五世卦。五陰爻陰世，從初爻午月起至五爻為戌，豐為九月卦。餘類推。</p><h3 id="八宮飛伏" tabindex="-1">八宮飛伏 <a class="header-anchor" href="#八宮飛伏" aria-label="Permalink to “八宮飛伏”">​</a></h3><p>世之所位，而陰陽之肆者謂之飛，陰陽肇乎所配 【乾與坤，震與巽，坎與離，艮與兌】 ，而終不脫乎本 【以飛某宮之卦，乃伏某宮之位】 。</p><p>以顯應佐神明者謂之伏。故有卦之飛伏，有爻之飛伏。《文言》曰：“同聲相應，同氣相求。”飛之與伏，聲氣相通，或顯或隱，各以類求。《中庸》曰：“莫現乎隱，莫顯乎微。”此精義入神之論也。後儒以經學自誇，謂孔子未嘗言此，指為術數小道，不知《十翼》之言飛伏者多矣。奈學者瞠目視之，皆未見耳。《雜卦傳》“兌見而巽伏也”，是明言飛伏之一例。《說卦》“坎為隱伏”，而《離? 象》“飛鳥”，亦飛伏之見端。而六十四卦《彖》、《象》言之者，更不勝枚舉也。</p><p>（☰ 乾飛） （☷ 坤伏） （☶ 艮飛） （☱ 兌伏）</p><p>（☲ 離飛） （☵ 坎伏） （☳ 震飛） （☴ 巽伏）</p><h3 id="月建、積算" tabindex="-1">月建、積算 <a class="header-anchor" href="#月建、積算" aria-label="Permalink to “月建、積算”">​</a></h3><p>《京氏易傳》以爻直月，從世起建，佈於六位 【惟乾坎二卦從初爻起】 。乾起甲子，坤起甲午。一卦凡六月，計一百八十日。積算以爻直日，即從月建所止之日起，如姤卦月建起庚午至乙亥 【姤初爻庚午，上爻乙亥】 ，積算即從乙亥起。上九為一日，週而復始，一卦凡百有八十日。今佔家用《火珠林》術，大半出於京氏。惟月建積算，罕有傳其法者。後人或以月為直符，日為傳符，指六爻所見之支當之，非其義也。此為京氏佔法，詳晁氏《別錄》，說繁不贅錄。</p><p>八純卦外，一至六世，皆以本宮納甲為伏，而變宮遊歸以爻論。詳下章。</p><p>八卦五行之用</p><p>《說卦》“帝出乎震”，及“神也者”兩節，皆言後天八卦之用者也。術家言後天八卦皆居旺地，語雖俚而所見甚精。蓋帝出乎震之帝，非專屬震卦。帝者主也，主權所在，即王也。術家曰旺，即土之用。《大平御覽? 五行休旺論》曰：“立春艮旺 【艮居醜寅之交，立春之候也】 ，震相，巽胎，離沒，坤死，兌囚，乾廢，坎休。立夏巽旺 【巽居辰巳之交，立夏之候也】 ，離相，坤胎，兌沒，乾死，坎囚，艮廢，震休。立秋坤旺 【坤居未申之交，立秋之候也】 ，兌相，乾胎，坎沒，艮死，震囚，坎廢，離休。立冬乾旺 【乾居戌亥之交，立冬之候也】 ，坎相，艮胎，震沒，離囚，坤廢，兌休 【《唐典》：王、相、胎、沒、休、廢為八卦之氣】 。”王充《論衡》亦同。蓋立冬之候也，得地為旺，旺之衝死，旺所生相，相之衝囚，胎之對廢，沒之對休。《淮南? 墜形訓》曰：“五行：木壯，水老，火生，金囚，土死。火壯，木老，土生，水囚，金死。土壯，火老，金生，木囚，水死。金壯，土老，水生，火囚，木死。水壯，金老，木生，土囚，火死。”</p><p>土王四季 金相</p><h3 id="十二卦地支藏用" tabindex="-1">十二卦地支藏用 <a class="header-anchor" href="#十二卦地支藏用" aria-label="Permalink to “十二卦地支藏用”">​</a></h3><p>地支藏用，分晰陰陽，最為精密。周天三百六十有五度四分度之一，歷三百六十五日四分日之一而氣周，即六十卦三百六十爻之爻周。坎離震兌，分主二至二分，共三百八十四爻。陰陽錯綜，消息盈虛，無不合矣。藏天干於地支者，即乾體坤用。乾之用九，用於坤六，學者以術家言而忽之。是猶悅琢玉之精美，而賤斧鑿為匠器。《十翼》造化之筆，因無斧鑿之痕。然不知斧鑿之用者，又安識良工之心苦哉！</p><p>䷗ 子 ：壬五日三分半，癸二十日六分半，辛長生。</p><p>䷒ 醜 ：癸九日二分半，辛三日一分，己十八日六分。</p><p>䷊ 寅 ：戊七日二分半，丙七日二分半，甲十六日五分。</p><p>䷡ 卯 ：甲十日三分半，乙二十日六分半，癸長生。</p><p>䷪ 辰 ：乙九日三分，癸二日一分半，戊十八日六分。</p><p>䷀ 巳 ：庚七日二分半，戊七日二分半，丙十六日五分。</p><p>䷫ 午 ：午丙十日三分半，己九日三分，丁十三日三分半。</p><p>䷠ 未 ：丁九十三分，乙三日一分半，己十分日六分。</p><p>䷋ 申 ：戊己共七日，壬七日三分半，庚十六日五分。</p><p>䷓ 酉 ：庚十日三分半，辛二十日六分半，丁長生。</p><p>䷖ 戌 ：辛九日三分，丁三日一分，戊十八日六分。</p><p>䷁ 亥 ：戊七日二分半，甲七日二分半，未十六日五分。</p>',44)])])}const f=a(i,[["render",s]]);export{_ as __pageData,f as default};
